[CmdletBinding()]
param([Parameter(Mandatory)][string]$Run,[Parameter(Mandatory)][guid]$Operacion,[Parameter(Mandatory)][ValidatePattern('^[a-f0-9]{64}$')][string]$ContenidoSHA256,[Parameter(Mandatory)][ValidatePattern('^[a-f0-9]{64}$')][string]$ProcedenciaSHA256,[Parameter(Mandatory)][guid]$Adjunto,[Parameter(Mandatory)][ValidatePattern('^[a-f0-9]{64}$')][string]$AdjuntoSHA256,[Parameter(Mandatory)][ValidateRange(1,262144000)][long]$Tamanio,[Parameter(Mandatory)][string]$Evidencia)
$ErrorActionPreference='Stop'
function Private-File([string]$Path){$p=[IO.Path]::GetFullPath($Path);if(-not $p.StartsWith('C:\req\',[StringComparison]::OrdinalIgnoreCase)){throw 'Fuera de laboratorio'};for($c=$p;$c;$c=[IO.Path]::GetDirectoryName($c)){if(Test-Path -LiteralPath $c){if((Get-Item -LiteralPath $c -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Enlace no permitido'}}};$allowed=@([Security.Principal.WindowsIdentity]::GetCurrent().User.Value,'S-1-5-18','S-1-5-32-544');foreach($r in (Get-Acl -LiteralPath $p).Access){if($r.AccessControlType -eq 'Allow' -and -not ($r.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly) -and $r.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -notin $allowed){throw 'ACL no privada'}}}
function Source-Bytes([string]$Name){$p='C:\req\config\origen-dpapi\'+$Name+'.dpapi';Private-File $p;return ,([Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($p),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser))}
if(-not $IsWindows -or $Run -notmatch '^C:\\req\\testdata\\runtime-qa-[a-f0-9]{32}$' -or -not ([IO.Path]::GetFullPath($Evidencia)).StartsWith('C:\req\evidencias\')){throw 'Solo QA Windows'}
Private-File $Run;Private-File $Evidencia;$state=Get-Content -LiteralPath (Join-Path $Run 'run.json') -Raw|ConvertFrom-Json
if(Get-NetTCPConnection -State Listen -LocalPort ([uri]$state.origin).Port -ErrorAction SilentlyContinue){throw 'Detener primero el runtime propio; no competir por el archivo'}
if($state.database -ne 'siger_institucional_windows_qa' -or $state.artifactSHA256 -ne '9897abd7cd0bd57df6f0199e28904517c10d650bd7dd2795e34b2aa7b85084bf' -or $state.archivo -notmatch '^C:\\req\\testdata\\runtime-qa-[a-f0-9]{32}\\archivo$' -or $state.integrationProfile -notmatch '^C:\\req\\config\\formulario-wsl-(integracion|e2e-[a-f0-9]{32})\\perfil\.json$'){throw 'Runtime/perfil distintos del candidato acordado'}
Private-File $state.archivo;Private-File $state.integrationProfile;$profile=Get-Content -LiteralPath $state.integrationProfile -Raw|ConvertFrom-Json;Private-File $profile.publicTrust
$jar='C:\req\bin\siger-9897abd7cd0bd57d.jar';Private-File $jar;if((Get-FileHash $jar).Hash.ToLowerInvariant() -ne $state.artifactSHA256){throw 'Candidato alterado'}
$root='C:\req\scratch\verificar-e2e-'+[guid]::NewGuid().ToString('N');$null=New-Item -ItemType Directory -Path $root
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip=[IO.Compression.ZipFile]::OpenRead($jar)
try{foreach($entry in $zip.Entries|Where-Object {$_.FullName -match '^BOOT-INF/classes/[A-Za-z0-9_/$.-]+\.class$'}){$target=Join-Path $root $entry.FullName.Substring(17);if(-not ([IO.Path]::GetFullPath($target)).StartsWith($root+'\') -or $entry.FullName.Contains('..')){throw 'Entrada invalida'};$null=[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target));[IO.Compression.ZipFileExtensions]::ExtractToFile($entry,$target,$false)}}finally{$zip.Dispose()}
$jdk='C:\Program Files\Eclipse Adoptium\jdk-25.0.4.101-hotspot\bin';$cp=$root+';C:\req\bin\lib\*'
& (Join-Path $jdk 'javac.exe') -cp $cp -d $root (Join-Path $PSScriptRoot 'qa\VerificarComunicacionE2E.java') *> (Join-Path $Evidencia 'verificador-compilacion.log');if($LASTEXITCODE){throw 'No compilo verificador'}
Add-Type -AssemblyName System.Security.Cryptography.ProtectedData
$key=$null;$own=$null;$process=$null;$credential=$null;$payload=$null
try{
 $key=Source-Bytes 'institucional-key.pem';$own=Source-Bytes 'institucional-trust.json';$credential=Import-Clixml C:\req\config\mysql-windows-qa-app.credential.xml;if($credential.UserName -ne 'siger_windows_qa_app'){throw 'Solo identidad DML QA'}
 $payload=@{user=$credential.UserName;password=$credential.GetNetworkCredential().Password;key=[Text.Encoding]::UTF8.GetString($key);own=([Text.Encoding]::UTF8.GetString($own)|ConvertFrom-Json);publicTrust=(Get-Content -LiteralPath $profile.publicTrust -Raw|ConvertFrom-Json);storage=$state.archivo;operation=$Operacion.ToString();contentSHA256=$ContenidoSHA256;provenanceSHA256=$ProcedenciaSHA256;attachment=$Adjunto.ToString();attachmentSHA256=$AdjuntoSHA256;size=$Tamanio}|ConvertTo-Json -Depth 6 -Compress
 $start=[Diagnostics.ProcessStartInfo]::new((Join-Path $jdk 'java.exe'));$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
 foreach($arg in @('--enable-native-access=ALL-UNNAMED','-XX:-UsePerfData','-Xmx128m','-cp',$cp,'VerificarComunicacionE2E')){$start.ArgumentList.Add($arg)}
 $process=[Diagnostics.Process]::Start($start);$out=$process.StandardOutput.ReadToEndAsync();$err=$process.StandardError.ReadToEndAsync();$process.StandardInput.Write($payload);$process.StandardInput.Close();$payload=$null
 if(-not $process.WaitForExit(45000)){$process.Kill($true);throw 'Verificacion vencida'};$null=$err.GetAwaiter().GetResult();$safe=@($out.GetAwaiter().GetResult() -split "`r?`n"|Where-Object {$_.StartsWith('{')})[-1]
 if($process.ExitCode -ne 0 -or -not $safe){throw 'E2E no acreditado; excepciones y valores privados omitidos'};$result=$safe|ConvertFrom-Json;$result|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $Evidencia 'verificacion-institucional.json');$safe
}finally{if($process){if(-not $process.HasExited){$process.Kill($true)};$process.Dispose()};foreach($bytes in @($key,$own)){if($bytes){[Security.Cryptography.CryptographicOperations]::ZeroMemory($bytes)}};$credential=$null;$payload=$null}
